// Auto-generated base64 styled template matching Accurate Online 2-sheet format
export const INVENTORY_ADJUSTMENT_TEMPLATE_BASE64 =
    '';

export function downloadInventoryAdjustmentTemplate() {
    try {
        const binaryString = atob(INVENTORY_ADJUSTMENT_TEMPLATE_BASE64);
        const bytes = new Uint8Array(binaryString.length);
        for (let i = 0; i < binaryString.length; i++) {
            bytes[i] = binaryString.charCodeAt(i);
        }
        const blob = new Blob([bytes], {
            type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = 'Template_Penyesuaian_Persediaan.xlsx';
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        setTimeout(() => URL.revokeObjectURL(url), 1000);
    } catch {
        window.location.href = '/templates/Template_Penyesuaian_Persediaan.xlsx';
    }
}
